  const enrollments=data.learning?.enrollments||[];
  const requests=manager?data.operations?.requests||[]:data.learning?.requests||[];
  const [enrollmentId,setEnrollmentId]=useState('');const [kind,setKind]=useState<'transfer'|'defer'|'withdraw'|'access_exception'|'resume'>('transfer');
